"""Build the standalone combined service and GNN evidence report."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
original=(root/'reports/demo/seed_42/portfolio.html').read_text()
summary=json.loads((root/'reports/gnn/multi_seed_summary.json').read_text())
metrics=json.loads((root/'reports/gnn/seed_42/metrics.json').read_text())
stress=json.loads((root/'reports/gnn/seed_42/structural_stress.json').read_text())
combined={'summary':summary,'metrics':metrics,'stress':stress}
style='''<style>.researchnav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px}.researchnav button[aria-selected="true"]{background:#087f8c;color:white;border-color:#087f8c}.researchhidden{display:none}.researchintro{font-size:16px;line-height:1.7}.researchgrid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.researchnum{font-size:32px;font-weight:600;color:#087f8c}@media(max-width:700px){.researchgrid{grid-template-columns:1fr}} </style>'''
nav='''<nav class="researchnav" aria-label="Report views"><button data-panel="servicePanel" aria-selected="true">Service demo</button><button data-panel="gnnPanel" aria-selected="false">GNN research</button><button data-panel="stabilityPanel" aria-selected="false">Structural stability</button></nav><div id="servicePanel">'''
research='''</div><section id="gnnPanel" class="researchhidden"><div class="panel"><span class="pill">Version 1.1 · Synthetic pilot</span><h2 style="margin-top:14px">Temporal GNNs, tested against simpler models.</h2><p class="researchintro">Learn from strictly earlier transactions connected through account and device relations. Compare a no-edge MLP, relational mean aggregation, temporal multi-head attention and risk-gated temporal attention on the same data and chronological stages as the original baselines.</p><p class="sub">This is a typed transaction projection with historical neighbor messages. Full HGT entity states and persistent TGN memory are future candidates. The operational service remains on its tabular model.</p></div><div class="researchgrid"><div class="panel"><h2>Inspect a candidate</h2><label for="gnnModel">Model family</label><select id="gnnModel" style="width:100%;margin:14px 0"></select><div id="gnnModelDetail"></div></div><div class="panel"><h2>Past-only risk guidance</h2><p>Supervised edge risk is generated by five expanding chronological teacher blocks. Each teacher sees only labels that matured before its score period. The later teacher is frozen at the training boundary.</p><p class="policy">No target labels or fraud-derived edge signs enter the graph. Equal-time and future edges are rejected. Missing identifiers do not form a shared supernode.</p></div></div><div class="panel"><h2>Three-seed comparison</h2><div class="table-wrap"><table><thead><tr><th>Family</th><th>Mean AP</th><th>AP SD</th><th>Mean recall at 5%</th></tr></thead><tbody id="gnnAll"></tbody></table></div><p class="sub">Independent synthetic populations. These differences are exploratory and are not significance tests. Neural models use fixed 12-epoch fits. A no-edge MLP still receives the original engineered behavioral features.</p><div id="gnnSelection" class="policy"></div></div></section><section id="stabilityPanel" class="researchhidden"><div class="panel"><span class="pill">Frozen weights · Seed 42</span><h2 style="margin-top:14px">Separate structure change from model response.</h2><p>Delete edges or rewire them to strictly earlier sources. Hold the model, calibrator and threshold fixed. Three perturbation draws are recorded for each condition.</p><label for="stressCondition">Perturbation</label><select id="stressCondition" style="width:100%;margin:14px 0"><option value="delete-0.1">Delete 10% of incoming test edges</option><option value="delete-0.3">Delete 30% of incoming test edges</option><option value="rewire-0.1">Rewire 10% of incoming test edges</option><option value="rewire-0.3">Rewire 30% of incoming test edges</option></select><div id="stressDetail" class="metricline"></div><p class="policy">Rewiring retains the target's indegree where possible but breaks actual entity membership. This is a controlled integrity stress. It does not model a verified attacker or prove robustness.</p></div><div class="panel"><h2>Your research connection</h2><p>The evidence separates raw relation-adjacency displacement, embedding drift, calibrated score drift and threshold flips. Matched retraining is a separate next study.</p><p>Signed or magnetic GNNs require valid scoring-time sign semantics. Fraud labels must never become edge signs. A direction reversal that creates a future-to-past information path is rejected by the causal graph contract.</p><p class="sub">Research context: BRIGHT (2022), HGT (2020), TGN (2020), and RGH-GNN (October 2026 preprint). The implementation is original and does not claim to reproduce those systems or their reported scores. Full sources and methods are in the project documentation.</p></div></section>'''
data='<script id="gnnData" type="application/json">'+json.dumps(combined,allow_nan=False).replace('</','<\\/')+'</script>'
script='''<script>
const gd=JSON.parse(document.getElementById('gnnData').textContent);const descriptions={no_edge_mlp:'Same current-feature neural backbone, with zero learned graph messages.',relational_sage:'Relation-specific mean aggregation of strictly earlier transaction encodings.',temporal_attention:'Four attention heads with relation-specific projections and relative time encoding.',risk_gated_attention:'Temporal attention with learned gates informed by past-only teacher risk.',logistic:'Original linear probability baseline with held-out calibration.',hist_gradient_boosting:'Original nonlinear tree baseline with held-out calibration.',isolation_forest:'Original unsupervised anomaly-ranking challenger.'};
for(const button of document.querySelectorAll('[data-panel]'))button.addEventListener('click',()=>{for(const other of document.querySelectorAll('[data-panel]')){const active=other===button;other.setAttribute('aria-selected',String(active));document.getElementById(other.dataset.panel).classList.toggle('researchhidden',!active);}});
for(const row of gd.summary.models){const option=el('option',row.model);option.value=row.model;by('gnnModel').append(option);const tr=el('tr');for(const value of [row.model,row.average_precision_mean.toFixed(4),row.average_precision_std.toFixed(4),pct(row.recall_at_5pct_mean)])tr.append(el('td',value));by('gnnAll').append(tr);}
function updateGnn(){const row=gd.summary.models.find(r=>r.model===by('gnnModel').value);const panel=by('gnnModelDetail');panel.replaceChildren(el('p',descriptions[row.model]));for(const [label,value]of [['Mean average precision',row.average_precision_mean.toFixed(4)],['Mean fraud recall at 5%',pct(row.recall_at_5pct_mean)]]){const r=el('div',undefined,'row evidence');r.append(el('span',label),el('strong',value,'researchnum'));panel.append(r)}}
by('gnnModel').value='risk_gated_attention';by('gnnModel').addEventListener('change',updateGnn);updateGnn();by('gnnSelection').textContent='Overall validation-cost choices: '+gd.summary.selection_by_seed.map(r=>'seed '+r.seed+': '+r.overall).join('; ')+'. No graph candidate wins the overall cost rule in this pilot.';
function updateStress(){const [kind,fraction]=by('stressCondition').value.split('-');const rows=gd.stress.filter(r=>r.kind===kind&&r.requested_fraction===Number(fraction));const mean=k=>rows.reduce((sum,r)=>sum+r[k],0)/rows.length;by('stressDetail').replaceChildren();for(const [label,value]of [['Mean score drift',mean('mean_absolute_score_drift').toFixed(4)],['Decision flips',pct(mean('threshold_flip_rate'))],['Perturbed AP',mean('average_precision').toFixed(4)]]){const item=el('div',label,'sub');item.append(el('strong',value));by('stressDetail').append(item)}}by('stressCondition').addEventListener('change',updateStress);updateStress();
</script>'''
original=original.replace('</head>',style+'</head>').replace('<main>','<main>'+nav).replace('<footer id="footer">',research+'<footer id="footer">').replace('</body>',data+script+'</body>')
(root/'reports/FraudScope_Interactive_Report.html').write_text(original)
print('Combined GNN report built')
